/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;

/**
 * Pieces of the viewer page shared by the page gateways.
 */
public final class ObservePages {

  /** Fragment of the viewer, kept out of the static resources so it is not served alone. */
  public static final String FRAGMENT = "observe-viewer/fragment-app.html";

  private ObservePages() {}

  /**
   * Fragment of the viewer with its options.
   *
   * @param brand {@code show} when the viewer draws its own brand, {@code hide} inside a theme
   *        layout that already has one
   * @param fit {@code viewport} for a standalone page, {@code container} inside a layout
   */
  public static String fragment(final String title, final String brand, final String fit) {
    try (InputStream in =
        Thread.currentThread().getContextClassLoader().getResourceAsStream(FRAGMENT)) {
      if (null == in) {
        throw new IllegalStateException("Missing viewer resource " + FRAGMENT);
      }
      String html = new String(in.readAllBytes(), StandardCharsets.UTF_8);
      return html.replace("{{title}}", escape(title)).replace("{{brand}}", brand).replace("{{fit}}",
          fit);
    } catch (IOException ex) {
      throw new UncheckedIOException(ex);
    }
  }

  /** Standalone page, without theme: the viewer with its own styles. */
  public static String standalone(final String title, final String body, final String lang) {
    return "<!DOCTYPE html>\n<html lang=\"" + escape(lang) + "\">\n<head>\n"
        + "<meta charset=\"UTF-8\">\n"
        + "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n" + "<title>"
        + escape(title) + "</title>\n"
        + "<link rel=\"stylesheet\" href=\"/observe/assets/brand.css\">\n"
        + "</head>\n<body class=\"obs-standalone\">\n" + body + "\n</body>\n</html>\n";
  }

  public static String escape(final String value) {
    if (null == value) {
      return "";
    }
    return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"",
        "&quot;");
  }
}
